use ruff_diagnostics::{AlwaysFixableViolation, Diagnostic, Edit, Fix};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::{self as ast, Expr, Stmt};
use ruff_python_semantic::{BindingKind, ScopeKind};
use ruff_python_trivia::{BackwardsTokenizer, SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::{Ranged, TextRange};

use crate::checkers::ast::Checker;

/// ## What it does
/// Checks for `for` loops that can be replaced with `yield from` expressions.
///
/// ## Why is this bad?
/// If a `for` loop only contains a `yield` statement, it can be replaced with a
/// `yield from` expression, which is more concise and idiomatic.
///
/// ## Example
/// ```python
/// for x in foo:
///     yield x
/// ```
///
/// Use instead:
/// ```python
/// yield from foo
/// ```
///
/// ## Fix safety
/// This rule's fix is marked as unsafe, as converting a `for` loop to a `yield
/// from` expression can change the behavior of the program in rare cases.
/// For example, if a generator is being sent values via `send`, then rewriting
/// to a `yield from` could lead to an attribute error if the underlying
/// generator does not implement the `send` method.
///
/// In most cases, however, the fix is safe, and such a modification should have
/// no effect on the behavior of the program.
///
/// ## References
/// - [Python documentation: The `yield` statement](https://docs.python.org/3/reference/simple_stmts.html#the-yield-statement)
/// - [PEP 380 – Syntax for Delegating to a Subgenerator](https://peps.python.org/pep-0380/)
#[derive(ViolationMetadata)]
pub(crate) struct YieldInForLoop;

impl AlwaysFixableViolation for YieldInForLoop {
    #[derive_message_formats]
    fn message(&self) -> String {
        "Replace `yield` over `for` loop with `yield from`".to_string()
    }

    fn fix_title(&self) -> String {
        "Replace with `yield from`".to_string()
    }
}

/// UP028
pub(crate) fn yield_in_for_loop(checker: &mut Checker, stmt_for: &ast::StmtFor) {
    let mut in_async_context = false;
    for scope in checker.semantic().current_scopes() {
        if let ScopeKind::Function(function_def) = scope.kind {
            in_async_context = function_def.is_async;
            break;
        }
    }
    if in_async_context {
        return;
    }

    let ast::StmtFor {
        target,
        iter,
        body,
        orelse,
        is_async: _,
        range: _,
    } = stmt_for;

    if !orelse.is_empty() {
        return;
    }

    let [body] = body.as_slice() else {
        return;
    };

    let Stmt::Expr(ast::StmtExpr { value, range: _ }) = &body else {
        return;
    };
    let Expr::Yield(ast::ExprYield {
        value: Some(value),
        range: _,
    }) = value.as_ref()
    else {
        return;
    };

    if !is_same_expr(target, value) {
        return;
    }

    let mut names_used_outside = false;
    for name in collect_names(value) {
        let mut bound_id = None;
        for id in checker.semantic().current_scope().get_all(name.id.as_str()) {
            let binding = &checker.semantic().bindings[id];
            let is_unbound = matches!(
                binding.kind,
                BindingKind::Annotation | BindingKind::Deletion | BindingKind::UnboundException(_)
            );
            if !is_unbound {
                bound_id = Some(id);
                break;
            }
        }
        if let Some(binding_id) = bound_id {
            let binding = &checker.semantic().bindings[binding_id];
            for reference_id in &binding.references {
                if checker.semantic().reference(*reference_id).range() != name.range() {
                    names_used_outside = true;
                    break;
                }
            }
        }
        if names_used_outside {
            break;
        }
    }
    if names_used_outside {
        return;
    }

    let source = checker.locator().contents();
    let comment_ranges = checker.comment_ranges();
    let iter_range = iter.range();
    let right_tokenizer =
        SimpleTokenizer::new(source, TextRange::new(iter_range.end(), stmt_for.end()))
            .skip_trivia()
            .take_while(|token| token.kind == SimpleTokenKind::RParen);
    let left_tokenizer = BackwardsTokenizer::up_to(iter_range.start(), source, comment_ranges)
        .skip_trivia()
        .take_while(|token| token.kind == SimpleTokenKind::LParen);
    let mut parenthesized = None;
    for (right, left) in right_tokenizer.zip(left_tokenizer) {
        parenthesized = Some(TextRange::new(left.start(), right.end()));
    }

    let mut diagnostic = Diagnostic::new(YieldInForLoop, stmt_for.range());
    let contents = checker.locator().slice(parenthesized.unwrap_or(iter_range));
    let contents = format!("yield from {contents}");
    diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
        contents,
        stmt_for.range(),
    )));
    checker.diagnostics.push(diagnostic);
}

/// Return `true` if the two expressions are equivalent, and both consistent solely
/// of tuples and names.
fn is_same_expr(left: &Expr, right: &Expr) -> bool {
    match (&left, &right) {
        (Expr::Name(left), Expr::Name(right)) => left.id == right.id,
        (Expr::Tuple(left), Expr::Tuple(right)) => {
            left.len() == right.len()
                && left
                    .iter()
                    .zip(right)
                    .all(|(left, right)| is_same_expr(left, right))
        }
        _ => false,
    }
}

/// Collect all named variables in an expression consisting solely of tuples and
/// names.
fn collect_names<'a>(expr: &'a Expr) -> Box<dyn Iterator<Item = &'a ast::ExprName> + 'a> {
    Box::new(
        expr.as_name_expr().into_iter().chain(
            expr.as_tuple_expr()
                .into_iter()
                .flat_map(|tuple| tuple.iter().flat_map(collect_names)),
        ),
    )
}

